from __future__ import annotations

import json
import os
from datetime import date, datetime
from decimal import Decimal
from typing import Any, Dict, List, Optional

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


def _to_iso_date(value: Any) -> Optional[str]:
    if value is None:
        return None

    if isinstance(value, str):
        s = value.strip()
        if not s:
            return None
        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%d/%m/%Y", "%m-%d-%Y", "%d-%m-%Y"):
            try:
                return datetime.strptime(s, fmt).date().isoformat()
            except ValueError:
                pass
        try:
            return datetime.fromisoformat(s.replace("Z", "+00:00")).date().isoformat()
        except ValueError:
            return s

    if isinstance(value, datetime):
        return value.date().isoformat()
    if isinstance(value, date):
        return value.isoformat()

    return str(value)


def _to_number(value: Any) -> Any:
    if value is None:
        return None

    if isinstance(value, (int, float)):
        return value

    if isinstance(value, Decimal):
        return float(value)

    if isinstance(value, str):
        s = value.strip().replace(",", "")
        if not s:
            return None
        try:
            if "." in s:
                return float(s)
            return int(s)
        except ValueError:
            return s

    return value


def _extract_field_value(field: Any) -> Any:
    if field is None:
        return None

    for attr in ("value", "content"):
        if hasattr(field, attr):
            v = getattr(field, attr)
            if v is not None:
                return v

    if hasattr(field, "value_type"):
        vt = getattr(field, "value_type", None)
        if vt == "date" and hasattr(field, "value_date"):
            return getattr(field, "value_date")
        if vt == "currency" and hasattr(field, "value_currency_code"):
            return {
                "amount": getattr(field, "value", None),
                "currency": getattr(field, "value_currency_code", None),
            }
        if vt == "number" and hasattr(field, "value_number"):
            return getattr(field, "value_number")
        if vt == "string" and hasattr(field, "value_string"):
            return getattr(field, "value_string")

    return field


def _get_field(result: Any, name: str) -> Any:
    if result is None:
        return None

    fields = getattr(result, "fields", None) or {}
    if name in fields:
        return _extract_field_value(fields[name])

    # Fallback for any mapping-like object
    if isinstance(result, dict):
        return result.get(name)

    return None


def _extract_line_items(result: Any) -> List[Dict[str, Any]]:
    items: List[Dict[str, Any]] = []
    for line in getattr(result, "documents", []) or []:
        fields = getattr(line, "fields", None) or {}
        for key in ("Items", "LineItems", "lineItems"):
            if key in fields:
                raw_items = _extract_field_value(fields[key])
                if isinstance(raw_items, list):
                    for item in raw_items:
                        item_fields = getattr(item, "value_array", None)
                        if item_fields is not None:
                            continue
                        item_map = getattr(item, "fields", None) or {}
                        extracted: Dict[str, Any] = {}
                        for k, v in item_map.items():
                            extracted[k] = _extract_field_value(v)
                        items.append(extracted)
                elif isinstance(raw_items, dict):
                    items.append(raw_items)
                return items

    # Azure prebuilt invoice commonly exposes line_items at top-level from result.documents[0].fields["Items"]
    if getattr(result, "documents", None):
        doc = result.documents[0]
        fields = getattr(doc, "fields", None) or {}
        for key in ("Items", "LineItems"):
            if key in fields:
                val = _extract_field_value(fields[key])
                if isinstance(val, list):
                    for it in val:
                        if hasattr(it, "fields"):
                            items.append({k: _extract_field_value(v) for k, v in (getattr(it, "fields", {}) or {}).items()})
                        elif isinstance(it, dict):
                            items.append(it)
                return items

    return items


def extract_invoice_fields(document_bytes: bytes, content_type: str = "application/pdf") -> Dict[str, Any]:
    """
    Extract vendor, date, total, and line-item fields from an invoice using Azure Document Intelligence.
    Required environment variables:
      - AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT
      - AZURE_DOCUMENT_INTELLIGENCE_KEY
    """
    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))

    poller = client.begin_analyze_document(
        model_id="prebuilt-invoice",
        body=document_bytes,
        content_type=content_type,
    )
    result = poller.result()

    vendor = _get_field(result, "VendorName") or _get_field(result, "MerchantName")
    invoice_date = _get_field(result, "InvoiceDate") or _get_field(result, "BillingDate")
    total = _get_field(result, "InvoiceTotal") or _get_field(result, "Total")

    if isinstance(total, dict):
        total_amount = _to_number(total.get("amount") or total.get("value"))
        currency = total.get("currency")
        total_value = {"amount": total_amount, "currency": currency} if currency else total_amount
    else:
        total_value = _to_number(total)

    if hasattr(vendor, "text"):
        vendor = getattr(vendor, "text")
    if hasattr(invoice_date, "text"):
        invoice_date = getattr(invoice_date, "text")
    if hasattr(total_value, "text"):
        total_value = getattr(total_value, "text")

    line_items = _extract_line_items(result)

    normalized_items: List[Dict[str, Any]] = []
    for item in line_items:
        normalized_items.append(
            {
                "description": item.get("Description") or item.get("ProductCode") or item.get("Name"),
                "quantity": _to_number(item.get("Quantity")),
                "unit_price": _to_number(item.get("UnitPrice") or item.get("UnitCost")),
                "amount": _to_number(item.get("Amount") or item.get("TotalPrice") or item.get("LineTotal")),
                "raw": item,
            }
        )

    return {
        "vendor": vendor,
        "date": _to_iso_date(invoice_date),
        "total": total_value,
        "line_items": normalized_items,
    }
